-- belief_sources: the channels Belief and Friends reads, and how (Jordan 2026-10-19: all state in PG).
-- Seeded from nova_friends.BELIEF_CHANNELS / BELIEF_SHARED_CHANNELS and nova_yt_direct.DIRECT_CHANNELS.
-- fetch_mode: 'subscription' = Jordan follows it (nova_yt_subs_audio's subscription list); 'direct' = ingested by
-- channel id without a subscription. owned_by_section: another section owns it; topic_only: only its
-- religion-topic videos count (nova_sections.is_belief_topic); nrm: capped per issue (new movements/sects).
BEGIN;
CREATE TABLE IF NOT EXISTS belief_families (
    name              text PRIMARY KEY,
    ord               int  NOT NULL UNIQUE,              -- rotation order (date ordinal % count)
    scripture_sources text[] NOT NULL DEFAULT '{}'       -- Nova's library vectors for Text in Context
);
CREATE TABLE IF NOT EXISTS belief_sources (
    channel_id       text PRIMARY KEY CHECK (channel_id ~ '^UC[\w-]{22}$'),
    name             text NOT NULL UNIQUE,               -- as the transcript memories carry it (metadata.channel)
    handle           text NOT NULL DEFAULT '',
    tradition        text NOT NULL,
    family           text NOT NULL REFERENCES belief_families(name),
    role             text NOT NULL CHECK (role IN ('scholar', 'insider', 'critic', 'counter-case', 'documentary')),
    fetch_mode       text NOT NULL CHECK (fetch_mode IN ('subscription', 'direct')),
    owned_by_section text,
    topic_only       boolean NOT NULL DEFAULT false,
    nrm              boolean NOT NULL DEFAULT false,
    active           boolean NOT NULL DEFAULT true,
    notes            text NOT NULL DEFAULT '',
    added_at         timestamptz NOT NULL DEFAULT now(),
    added_by         text NOT NULL DEFAULT 'claude'
);
DROP VIEW IF EXISTS belief_coverage;
-- per base tradition ('Islam (Shia)' -> 'Islam'): active channels, the branches covered, roles present and the
-- scholar/insider/critic slots still empty. Videos per tradition live in nova_memories — nova_friends
-- belief_coverage() adds those for the edition log.
CREATE VIEW belief_coverage AS
    WITH s AS (SELECT split_part(tradition, ' (', 1) AS tradition, tradition AS branch, family, role, active
                 FROM belief_sources)
    SELECT tradition, min(family) AS family,
           count(*) FILTER (WHERE active)                                      AS active_channels,
           array_agg(DISTINCT branch ORDER BY branch) FILTER (WHERE active)    AS branches,
           array_agg(DISTINCT role ORDER BY role) FILTER (WHERE active)        AS roles,
           array(SELECT r FROM unnest(ARRAY['scholar','insider','critic']) r
                 WHERE r <> ALL (coalesce(array_agg(role) FILTER (WHERE active), '{}')))  AS missing_roles
      FROM s GROUP BY tradition;

COMMIT;
